// Node 2 — Search queries
// Emits ONE ITEM PER QUERY so the next HTTP node runs once per query.
// Month/year come from $now, so this keeps working without edits.

const month = $now.toFormat('MMMM');
const year = $now.toFormat('yyyy');

const queries = [
  `trending products ${month} ${year} tiktok`,
  `viral products ${month} ${year} amazon`,
  `best selling dropshipping products ${month} ${year}`,
  `tiktok shop trending products this week`,
];

return queries.map((query) => ({ json: { query } }));

// Node 4 — Flatten results
// Input: one item per Serper response (4 of them).
// Output: ONE item with a single text blob, capped at 12,000 characters.

const CHAR_CAP = 12000;

const lines = [];
const seen = new Set();

for (const item of $input.all()) {
  const body = item.json.body ?? item.json;
  const organic = Array.isArray(body.organic) ? body.organic : [];

  for (const result of organic) {
    const title = String(result.title ?? '').replace(/\s+/g, ' ').trim();
    const snippet = String(result.snippet ?? '').replace(/\s+/g, ' ').trim();
    const link = String(result.link ?? '').trim();
    if (!title && !snippet) continue;

    const key = (title + '|' + snippet).toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);

    lines.push(link ? `${title} — ${snippet} [${link}]` : `${title} — ${snippet}`);
  }
}

// Cap on a whole-result boundary so Claude never reads a half-truncated entry.
let blob = '';
let used = 0;
for (const line of lines) {
  if (used + line.length + 1 > CHAR_CAP) break;
  blob += line + '\n';
  used += line.length + 1;
}

return [{ json: { blob: blob.trim(), resultCount: lines.length, blobChars: blob.trim().length } }];

// Node 6 — Parse and filter
// Reads Claude's reply, strips fences, parses JSON, drops score < 6, sorts desc.
// Emits ONE ITEM PER PRODUCT (all of them, including the ones filtered out) so
// the Google Sheets node can log every row. Each item also carries the same
// `hasProducts` flag and prebuilt `message`, which the IF and Telegram nodes use.

const SCORE_THRESHOLD = 6;
const TOP_N = 5;

const date = $now.toFormat('yyyy-MM-dd');

const incoming = $input.first().json;
const body = incoming.body ?? incoming;

let text = '';
try {
  text = body.content[0].text;
} catch (e) {
  text = typeof body === 'string' ? body : JSON.stringify(body);
}

function stripFences(s) {
  return String(s || '')
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```\s*$/, '')
    .trim();
}

function sliceArray(s) {
  const start = s.indexOf('[');
  const end = s.lastIndexOf(']');
  if (start === -1 || end === -1 || end < start) return null;
  return s.slice(start, end + 1);
}

// Telegram legacy Markdown does not reliably honour backslash escapes, so the
// safe move is to remove the characters that break a message rather than escape
// them. Anything with _ * ` [ ] in it would otherwise fail to send.
function clean(v) {
  return String(v ?? '')
    .replace(/[_*`\[\]]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function num(v) {
  const n = Number(v);
  return Number.isFinite(n) ? Math.round(n * 100) / 100 : null;
}

function money(v) {
  const n = num(v);
  return n === null ? '?' : n;
}

let parsed;
try {
  const cleaned = stripFences(text);
  try {
    parsed = JSON.parse(cleaned);
  } catch (e) {
    const arr = sliceArray(cleaned);
    if (!arr) throw e;
    parsed = JSON.parse(arr);
  }
  if (!Array.isArray(parsed)) throw new Error('Expected a JSON array');
} catch (err) {
  // Never fail the workflow on a bad response — report it downstream instead.
  return [{
    json: {
      error: true,
      raw: String(text).slice(0, 500),
      hasProducts: false,
      passed: false,
      message: '',
      date,
      product: '(parse error)',
      score: 0,
      est_retail_usd: null,
      est_landed_usd: null,
      reason: 'Claude response could not be parsed as JSON',
      risk: String(err.message).slice(0, 200),
    },
  }];
}

const scored = parsed
  .map((p) => {
    const rawScore = Number(p.score);
    const score = Number.isFinite(rawScore)
      ? Math.min(10, Math.max(0, Math.round(rawScore)))
      : 0;
    return {
      date,
      product: String(p.product ?? '').replace(/\s+/g, ' ').trim(),
      score,
      est_retail_usd: num(p.est_retail_usd),
      est_landed_usd: num(p.est_landed_usd),
      reason: String(p.reason ?? '').replace(/\s+/g, ' ').trim(),
      risk: String(p.risk ?? '').replace(/\s+/g, ' ').trim(),
      source_url: p.source_url ?? null,
    };
  })
  .filter((p) => p.product.length > 0);

scored.sort((a, b) => b.score - a.score);

const survivors = scored.filter((p) => p.score >= SCORE_THRESHOLD);
const hasProducts = survivors.length > 0;

let message = '';
if (hasProducts) {
  const top = survivors.slice(0, TOP_N);
  message = `*Product scan — ${date}*\n\n`;
  top.forEach((p, i) => {
    message += `*${i + 1}. ${clean(p.product)} — ${p.score}/10*\n`;
    message += `${clean(p.reason)}\n`;
    message += `Retail ~$${money(p.est_retail_usd)} | Landed ~$${money(p.est_landed_usd)}\n`;
    message += `Risk: ${clean(p.risk)}\n\n`;
  });
  message += '_Prices are estimates. Verify on AliExpress before buying._';
}

// Claude returned a well-formed but empty array: still emit one item so the IF
// node fires and the "nothing found" Telegram message goes out.
if (scored.length === 0) {
  return [{
    json: {
      error: false,
      hasProducts: false,
      passed: false,
      message: '',
      date,
      product: '(no products extracted)',
      score: 0,
      est_retail_usd: null,
      est_landed_usd: null,
      reason: 'Search results contained no shippable physical products',
      risk: '',
    },
  }];
}

return scored.map((p) => ({
  json: {
    ...p,
    error: false,
    hasProducts,
    passed: p.score >= SCORE_THRESHOLD,
    message,
  },
}));
